unitsize(0.2cm);
pair A,B,C,D,I,F,G,H;
A=(0,0);
B=(36,0);
I=(18,0);
H=(20,0);
D=(16,12);
C=(20,12);
G=(18,12);
F=(21.6,10.8);
dot(F);
dot(I);
dot(G);
draw(Circle((18,6),6),linewidth(0.7));
draw(A--B--C--D--cycle,linewidth(0.7));
draw(G--I,linewidth(0.7));
draw(C--H,linewidth(0.7));
label("2",(19,12),N);
draw((20,-2)--(36,-2));
draw((18,-4)--(36,-4));
draw((20,-2.5)--(20,-1.5));
draw((36,-2.5)--(36,-1.5));
draw((18,-3.5)--(18,-4.5));
draw((36,-3.5)--(36,-4.5));
